from pathlib import Path
import json,subprocess,tempfile,datetime,os,argparse
parser=argparse.ArgumentParser();parser.add_argument('--output-root',default='docs/phase11');parser.add_argument('--image',default='mintbot:phase11-readonly');parser.add_argument('--result-name',default='performance-node22');args_config=parser.parse_args()
root=Path.cwd();out=root/args_config.output_root;before=Path(json.loads((out/'performance-baseline.json').read_text())['root']);io=Path(tempfile.mkdtemp(prefix='mintbot-phase11-node22-disk-'))
args=['docker','run','--rm','--network','none','--read-only','--cap-drop','ALL','--security-opt','no-new-privileges','--mount',f'type=bind,source={root},target={root},readonly','--mount',f'type=bind,source={before},target={before},readonly','--mount',f'type=bind,source={io},target=/tmp','--mount',f'type=bind,source={out},target=/results','--workdir',str(root),args_config.image,'node','--import','tsx','scripts/phase9-performance-benchmark.ts','--before-root',str(before),'--runs','3','--paired-order','--scenarios','durable-burst-200,concurrent-history-live,slow-unavailable-rpc','--load-scope','Node22 disk-backed alternating pairs; no Mintbot monitor/build/test/DB jobs intentionally concurrent; other host processes uncontrolled','--output','/results/'+args_config.result_name+'.json']
meta={'args':args,'startedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'ioDirectory':str(io),'ioDevice':io.stat().st_dev,'hostTmpDevice':Path('/tmp').stat().st_dev,'filesystem':subprocess.check_output(['stat','-f','-c','%T',str(io)],text=True).strip(),'scope':'Real host filesystem bind, no tmpfs; file and directory fsync unchanged. Same dependencies, alternating job order; no claim of physical device isolation.'}
(out/('performance-command.json' if args_config.result_name=='performance-node22' else args_config.result_name+'-command.json')).write_text(json.dumps(meta,indent=2)+'\n')
with (out/(args_config.result_name+'.log')).open('w') as log:r=subprocess.run(args,stdout=log,stderr=subprocess.STDOUT)
raise SystemExit(r.returncode)
